  (SELECT count(*) FROM a WHERE public.old_ais(a.id,'partial')),(SELECT count(*) FROM a WHERE public.old_ais(a.id,'reader')),(SELECT count(*) FROM a WHERE public.old_unowned(a.id,'editor')),(SELECT count(*) FROM a WHERE public.old_mine(a.id));
END LOOP; END $$;
-- anon reading the view and table under the commit's grants
SELECT set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE anon;
SELECT count(*) AS anon_view_rows FROM public.accounts_in_my_partial_spaces;
RESET ROLE;
-- volume
INSERT INTO auth.users(id, instance_id, aud, role, email) SELECT gen_random_uuid(),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','b'||g||'@x.test' FROM generate_series(1,3000) g;
WITH i AS (INSERT INTO public."Space"(url,name,platform) SELECT 'https://b/'||g,'b'||g,'Roam' FROM generate_series(1,2000) g RETURNING id)
INSERT INTO public."SpaceAccess"(account_uid,space_id,permissions) SELECT (SELECT id FROM auth.users WHERE email='b'||(1+(i.id%3000))||'@x.test'), i.id,'editor' FROM i;
WITH i AS (INSERT INTO public."PlatformAccount"(name,platform,account_local_id) SELECT 'b'||g,'Roam','bacc'||g FROM generate_series(1,20000) g RETURNING id)
INSERT INTO public."LocalAccess"(account_id,space_id) SELECT i.id, sp.id FROM i JOIN LATERAL (SELECT id FROM public."Space" WHERE url LIKE 'https://b/%' AND i.id IS NOT NULL ORDER BY random() LIMIT 1) sp ON true;
INSERT INTO public."SpaceAccess"(account_uid,space_id,permissions) SELECT (SELECT id FROM u WHERE n=1), id,'reader' FROM public."Space" WHERE url LIKE 'https://b/1%' ON CONFLICT DO NOTHING;
INSERT INTO public."AgentIdentifier"(account_id,value,identifier_type) SELECT account_id,'v'||account_id||'@x','email' FROM public."LocalAccess" WHERE account_id%2=0 ON CONFLICT DO NOTHING;
ANALYZE public."PlatformAccount"; ANALYZE public."LocalAccess"; ANALYZE public."SpaceAccess"; ANALYZE public."AgentIdentifier";
SELECT set_config('request.jwt.claims', json_build_object('sub',(SELECT id FROM u WHERE n=1))::text, true);
SET LOCAL ROLE authenticated;
\echo == PA full read
EXPLAIN (ANALYZE, BUFFERS OFF, TIMING OFF, SUMMARY ON, COSTS OFF) SELECT id FROM public."PlatformAccount";
\echo == PA point read
EXPLAIN (ANALYZE, BUFFERS OFF, TIMING OFF, SUMMARY ON, COSTS OFF) SELECT id FROM public."PlatformAccount" WHERE id=(SELECT min(id) FROM public."LocalAccess"  l where l.account_id is not null);
\echo == AI full read
EXPLAIN (ANALYZE, BUFFERS OFF, TIMING OFF, SUMMARY ON, COSTS OFF) SELECT * FROM public."AgentIdentifier";
\echo == LA full read
EXPLAIN (ANALYZE, BUFFERS OFF, TIMING OFF, SUMMARY ON, COSTS OFF) SELECT * FROM public."LocalAccess";
\echo == AI update all
EXPLAIN (ANALYZE, BUFFERS OFF, TIMING OFF, SUMMARY ON, COSTS OFF) UPDATE public."AgentIdentifier" SET trusted=trusted;
\echo == PA update all
EXPLAIN (ANALYZE, BUFFERS OFF, TIMING OFF, SUMMARY ON, COSTS OFF) UPDATE public."PlatformAccount" SET name=name;
RESET ROLE;
ROLLBACK;
